-- OMNII: expanded canonical universal capability registry
-- This migration extends the existing Common Primitive Registry.
-- It does not create a second registry or constitutional kernel.

on conflict (key) do update set
  semantic_class = excluded.semantic_class,
  layer_role = excluded.layer_role,
  canonical_backing = excluded.canonical_backing,
  lifecycle = excluded.lifecycle,
  description = excluded.description,
  provenance = excluded.provenance,
  updated_at = now();

comment on table public.omnii_common_primitives is 'Canonical registry of reusable Common Layer semantics; expanded 2026-09-06 without creating a second constitutional kernel.';
